import{_ as t}from"./chunks/protocol.BCHVaPua.js";import{_ as o,o as i,c as r,a2 as a}from"./chunks/framework.BefGvJmu.js";const f=JSON.parse('{"title":"PAI Content Protocol","description":"Service discovery, authenticated publication, updates, and content retrieval in PAI content profile 0.1.0-draft.1.","frontmatter":{"title":"PAI Content Protocol","description":"Service discovery, authenticated publication, updates, and content retrieval in PAI content profile 0.1.0-draft.1."},"headers":[],"relativePath":"protocol.md","filePath":"protocol.md"}'),n={name:"protocol.md"};function s(d,e,c,l,p,h){return i(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="pai-content-protocol" tabindex="-1">PAI Content Protocol <a class="header-anchor" href="#pai-content-protocol" aria-label="Permalink to &quot;PAI Content Protocol&quot;">​</a></h1><p>Protocol <code>0.1.0-draft.1</code> · Profile <code>content</code></p><p>PAI clients publish, update, and retrieve documents through a selected service. The server validates uploaded files, enforces publisher ownership, stores publication versions, and exposes their content and original files.</p><h2 id="participants" tabindex="-1">Participants <a class="header-anchor" href="#participants" aria-label="Permalink to &quot;Participants&quot;">​</a></h2><ul><li><strong>Host application:</strong> an AI application or Harness that uses a PAI client.</li><li><strong>Client:</strong> discovers service capabilities and issues publication or retrieval requests.</li><li><strong>Server:</strong> implements the content interfaces within a service. The service provider operates its accounts, credentials, storage, and user interface.</li></ul><p><img src="'+t+'" alt="Publisher and reader clients exchange content with one selected PAI service."></p><h2 id="http-operations" tabindex="-1">HTTP operations <a class="header-anchor" href="#http-operations" aria-label="Permalink to &quot;HTTP operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Request target</th><th>Result</th></tr></thead><tbody><tr><td>Discover</td><td><code>GET /.well-known/pai.json</code></td><td>Capabilities, formats, authentication scheme, and endpoint URLs</td></tr><tr><td>Publish</td><td><code>POST endpoints.documents</code></td><td>A resource and its publication version</td></tr><tr><td>Update</td><td><code>PUT resource.updateUrl</code></td><td>A new version or the matching stored snapshot</td></tr><tr><td>List resources</td><td><code>GET endpoints.resources</code></td><td>Latest resource metadata in an <code>items</code> array</td></tr><tr><td>Read content</td><td><code>GET representations.content</code></td><td><code>resource</code>, <code>document</code>, ordered <code>blocks</code>, and <code>assets</code></td></tr><tr><td>Download</td><td><code>GET representations.download</code></td><td>The original file stored for that version</td></tr></tbody></table><p>Clients follow URLs returned by discovery and resource responses. Publication and updates send the complete <code>.pai</code> or <code>.pai.html</code> file as raw request bytes.</p><p>Writes use <code>Authorization: Bearer &lt;credential&gt;</code>. The server derives the publisher identity from that credential. Discovery and published content are publicly readable. Network deployments use HTTPS; loopback development services may use HTTP.</p><h2 id="identifiers-and-versions" tabindex="-1">Identifiers and versions <a class="header-anchor" href="#identifiers-and-versions" aria-label="Permalink to &quot;Identifiers and versions&quot;">​</a></h2><p><code>document.id</code> identifies the document across file forms. Its integer <code>revision</code> increments when content changes. The service assigns a resource ID and a publication <code>version</code> starting at <code>&quot;1&quot;</code>.</p><p>A higher document revision creates the next publication version. Repeating the same revision and content returns the stored snapshot with <code>200</code>, including for a historical revision. Reusing a revision with different content returns <code>409 document_revision_conflict</code>. An older revision that has never been published returns <code>409 stale_document_revision</code>.</p><p>Each returned block contains <code>id</code>, <code>markdown</code>, and <code>sourceUrl</code>. The source URL identifies the block in a specific publication snapshot. Subsequent updates preserve earlier text, original images, and source URLs. Image bytes are extracted from that version&#39;s downloaded file using the asset ID and declared packaging format.</p><h2 id="specifications-and-implementation" tabindex="-1">Specifications and implementation <a class="header-anchor" href="#specifications-and-implementation" aria-label="Permalink to &quot;Specifications and implementation&quot;">​</a></h2><p><a href="/pai-website/spec/service.html">Service specification</a> · <a href="/pai-website/spec/terminology.html">Terminology</a> · <a href="/pai-website/guide/client.html">Client integration</a> · <a href="/pai-website/guide/server.html">Server integration</a> · <a href="/pai-website/guide/architecture.html">Architecture</a></p>',16)])])}const v=o(n,[["render",s]]);export{f as __pageData,v as default};
